<script setup>
import yfpsGet from './components/yfpsGet.vue'
import yfpsCard from './components/yfpsCard.vue'
import { ref, onMounted, computed, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'

const router = useRouter()
const songList = ref({})
const selectedYear = ref('2026')

const yearConfig = {
  2020: {
    color: '#5E5B5E',
    text: '#FFFFFF',
    file: '/files/yfps/list2020.json'
  },
  2021: {
    color: '#2A3053',
    text: '#FFFFFF',
    file: '/files/yfps/list2021.json'
  },
  2022: {
    color: '#895C8E',
    text: '#FFFFFF',
    file: '/files/yfps/list2022.json'
  },
  2023: {
    color: '#7D4751',
    text: '#FFFFFF',
    file: '/files/yfps/list2023.json'
  },
  2024: {
    color: '#373D52',
    text: '#ffffff',
    file: '/files/yfps/list2024.json'
  },
  2025: {
    color: '#42469F',
    text: '#ffffff',
    file: '/files/yfps/list2025.json'
  },
  2026: {
    color: '#C280B0',
    text: '#ffffff',
    file: '/files/yfps/list2026.json'
  },
}

const yearColor = computed(() => yearConfig[selectedYear.value].color)
const yearTextColor = computed(() => yearConfig[selectedYear.value].text)

const fetchSongData = async () => {
  const filePath = yearConfig[selectedYear.value].file
  const data = await yfpsGet.methods.getYFPS(filePath)
  songList.value = data
}

const changeYear = (year) => {
  selectedYear.value = year
  fetchSongData()
}

onMounted(() => {
  fetchSongData()
})

const goToTable = (tableName) => {
  router.push({ name: tableName })
}

const handleLink = (link) => {
  if (link.startsWith('/') || !link.includes('http')) {
    goToTable(link)
  } else {
    window.open(link, '_blank')
  }
}
</script>

<template>
  <div class="song-container">
    <div class="year-tabs">
      <button
        :class="['year-btn', { active: selectedYear === '2020' }]"
        @click="changeYear('2020')"
        :style="{ 
          backgroundColor: selectedYear === '2020' ? yearColor : '#f5f5f5', 
          color: selectedYear === '2020' ? yearTextColor : '#000000' 
        }"
      >
        2020
      </button>
      <button
        :class="['year-btn', { active: selectedYear === '2021' }]"
        @click="changeYear('2021')"
        :style="{ 
          backgroundColor: selectedYear === '2021' ? yearColor : '#f5f5f5', 
          color: selectedYear === '2021' ? yearTextColor : '#000000' 
        }"
      >
        2021
      </button>
      <button
        :class="['year-btn', { active: selectedYear === '2022' }]"
        @click="changeYear('2022')"
        :style="{ 
          backgroundColor: selectedYear === '2022' ? yearColor : '#f5f5f5', 
          color: selectedYear === '2022' ? yearTextColor : '#000000' 
        }"
      >
        2022
      </button>
      <button
        :class="['year-btn', { active: selectedYear === '2023' }]"
        @click="changeYear('2023')"
        :style="{ 
          backgroundColor: selectedYear === '2023' ? yearColor : '#f5f5f5', 
          color: selectedYear === '2023' ? yearTextColor : '#000000' 
        }"
      >
        2023
      </button>
      <button
        :class="['year-btn', { active: selectedYear === '2024' }]"
        @click="changeYear('2024')"
        :style="{ 
          backgroundColor: selectedYear === '2024' ? yearColor : '#f5f5f5', 
          color: selectedYear === '2024' ? yearTextColor : '#000000' 
        }"
      >
        2024
      </button>
      <button
        :class="['year-btn', { active: selectedYear === '2025' }]"
        @click="changeYear('2025')"
        :style="{ 
          backgroundColor: selectedYear === '2025' ? yearColor : '#f5f5f5', 
          color: selectedYear === '2025' ? yearTextColor : '#000000' 
        }"
      >
        2025
      </button>
      <button
        :class="['year-btn', { active: selectedYear === '2026' }]"
        @click="changeYear('2026')"
        :style="{ 
          backgroundColor: selectedYear === '2026' ? yearColor : '#f5f5f5', 
          color: selectedYear === '2026' ? yearTextColor : '#000000' 
        }"
      >
        2026
      </button>
    </div>

    <div class="card-grid">
      <div 
        v-for="(songItem, songKey) in songList" 
        :key="songKey" 
        class="grid-item"
      >
        <yfps-card 
          :song-data="songItem" 
          :song-key="songKey" 
          :main-color="yearColor"
          :text-color="yearTextColor" 
        />
      </div>
    </div>
  </div>
</template>

<style scoped>
.song-container {
  max-width: 15rem;
  margin: 0 auto;
  padding: 0.2rem;
}

.year-tabs {
  display: flex;
  gap: 0.08rem;
  margin-bottom: 0.24rem;
  flex-wrap: wrap;
}

.year-btn {
  padding: 0.06rem 0.16rem;
  border: none;
  font-size: 0.18rem;
  font-weight: 500;
  cursor: pointer;
  user-select: none;
}

.year-btn.active {
  box-shadow: 0 0.02rem 0.06rem rgba(0,0,0,0.15);
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.2rem;
}

.grid-item {
  width: 100%;
}
</style>