import { createRouter, createWebHashHistory } from 'vue-router'
import Layout from './Layout.vue'
import startPage from './startPage.vue'
import tableMain from './tableMain.vue'
import tableLevel from './tableLevel.vue'
import tableB30 from './tableB30.vue'
import tableBPM from './tableBPM.vue'
import tableInfo from './tableInfo.vue'
import singleMain from './singleMain.vue'
import accountMain from './accountMain.vue'
import pmtMain from './pmtMain.vue'
import yfpsMain from './yfpsMain.vue'
import lvmdfMain from './lvmdfMain.vue'
import pmtPlayer from './pmtPlayer.vue'
import tableCharter from './tableCharter.vue'
import guiPage from './guiPage.vue'
import linkGUI from './linkGUI.vue'

const routes = [
  {
    path: '/',
    component: Layout,
    children: [
      {
        path: '',
        name: 'start',
        component: startPage
      },

      {
        path: 'table',
        name: 'tableMain',
        component: tableMain
      },
      {
        path: 'table',
        children: [
          { path: 'level', name: 'tableLevel', component: tableLevel },
          { path: 'b30', name: 'tableB30', component: tableB30 },
          { path: 'bpm', name: 'tableBPM', component: tableBPM },
          //{ path: 'info', name: 'tableInfo', component: tableInfo },
          { path: 'charter', name: 'tableCharter', component: tableCharter },
        ]
      },
      { path: 'single/:songName?', name: 'singleMain', component: singleMain, props: true },
      //{ path: 'account', name: 'accountMain', component: accountMain },
      { path: 'pmtMaps', name: 'pmtMain', component: pmtMain },
      { path: 'pmtStatus', name: 'pmtPlayer', component: pmtPlayer },
      { path: 'yfpsList', name: 'yfpsMain', component: yfpsMain },
      { path: 'lvmdfList', name: 'lvmdfMain', component: lvmdfMain },

      //{path: 'gui', name: 'gui', component: guiPage },
      {path: '/gui/phiLink', name: 'linkGUI', component: linkGUI }

    ]
  },
  { path: '/:pathMatch(.*)*', redirect: { name: 'start' } }
]

const router = createRouter({
  history: createWebHashHistory(),
  routes,
  scrollBehavior() {
    return { top: 0 }
  }
})

export default router