<script>
import axios from 'axios'

export default {
  name: 'CharterGet',
  methods: {
    async getCharter(jsonPath) {
      const net = '' 
      const net_files = `${net}/files`

      const difColor_map = {
        'EZ': '#0D9A28',
        'HD': '#0175B8',
        'IN': '#CF1313',
        'AT': '#383838',
        'LY': '#383838',
        'SP': '#383838'
      }

      try {
        const response = await axios.get(jsonPath)
        const jsonData = response.data

        for (const groupKey of Object.keys(jsonData)) {
          const group = jsonData[groupKey]
          
          for (const songId of Object.keys(group)) {
            const song = group[songId]
            song.cover = `${net}/assets/illLow/${songId}.png`

            for (const diff of ['EZ', 'HD', 'IN', 'AT','LY','SP']) {
              if (song[diff]) {
                song[diff].color = difColor_map[diff]
              }
            }
          }
        }

        return jsonData;

      } catch (error) {
        console.error('获取数据失败：', error)
        console.error('请求路径：', jsonPath)
        return {}
      }
    }
  }
}
</script>